// One brand per item -> build the search query.
const brandRaw = ($json.brand_name || '').toString().trim();
const brand_normalized = ($json.brand_normalized || brandRaw.toLowerCase()).trim();
const year = new Date().getFullYear();
const query = `${brandRaw} boycott campaign ${year} why boycotting reason`;
return [{ json: { brand: brandRaw, brand_normalized, query } }];

// Build grounding context + real signals. 'ctx' comes from the Build Query node in THIS iteration.
const ctx = $('Build Query').item.json;
const tav = $input.first().json;
const raw = tav.results || [];
const results = raw.map(r => ({
  title: r.title,
  url: r.url,
  content: (r.content || '').slice(0, 800),
  published_date: r.published_date || null
}));

let newestDays = null;
for (const r of results) {
  if (r.published_date) {
    const d = (Date.now() - new Date(r.published_date).getTime()) / 86400000;
    if (!isNaN(d) && (newestDays === null || d < newestDays)) newestDays = d;
  }
}

const sourceList = results.map((r, i) =>
  `[${i + 1}] ${r.title}\nURL: ${r.url}\nDate: ${r.published_date || 'unknown'}\n${r.content}`
).join('\n\n');

const system = 'You are a neutral research assistant. You are given web search results about whether a brand faces a consumer boycott. Use ONLY the information in the results. Do not use prior knowledge. Do not invent URLs. Stay neutral and take no side. If the results do not clearly describe a boycott of this brand, set status to "no_evidence". Respond with ONLY a JSON object and no other text.';

const user = `Brand: ${ctx.brand}\n\nSearch results:\n${sourceList || '(no results returned)'}\n\nReturn a JSON object with exactly these fields:\n{\n  "status": "active_boycott" | "no_evidence" | "unclear",\n  "reason": "short neutral summary of why people boycott, or empty string",\n  "who_is_calling": "who is calling for the boycott, or empty string",\n  "authority_level": "high" | "medium" | "low",\n  "used_source_urls": ["urls from the results you relied on"]\n}`;

const payload = {
  model: $env.LLM_MODEL || 'gpt-4o-mini',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: user }
  ]
};

return [{ json: { ...ctx, results, signals: { sourceCount: results.length, newestDays }, llmPayload: payload } }];

const ctx = $('Build LLM Context').item.json;
const resp = $input.first().json;
let content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '{}';
let parsed;
try { parsed = JSON.parse(content); } catch (e) {
  parsed = { status: 'unclear', reason: '', who_is_calling: '', authority_level: 'low', used_source_urls: [] };
}

const sourceCount = (ctx.signals && ctx.signals.sourceCount) || 0;
const newestDays = ctx.signals ? ctx.signals.newestDays : null;

const sourceScore = Math.min(sourceCount, 6) / 6 * 45;
let recencyScore;
if (newestDays === null) recencyScore = 5;
else if (newestDays <= 7)   recencyScore = 30;
else if (newestDays <= 30)  recencyScore = 22;
else if (newestDays <= 180) recencyScore = 12;
else                        recencyScore = 4;
const authScore = parsed.authority_level === 'high' ? 25 : parsed.authority_level === 'medium' ? 15 : 6;

let confidence = Math.round(sourceScore + recencyScore + authScore);
if (parsed.status === 'no_evidence') confidence = Math.min(confidence, 12);
if (parsed.status === 'unclear')     confidence = Math.min(confidence, 45);
confidence = Math.max(0, Math.min(100, confidence));

let cited = ctx.results.filter(r => (parsed.used_source_urls || []).includes(r.url));
if (cited.length === 0) cited = ctx.results;
const sources = cited.slice(0, 8).map(r => ({ title: r.title, url: r.url, date: r.published_date }));

const notes = `Confidence = likelihood that an active boycott exists, derived from source count (${sourceCount})` +
  (newestDays !== null ? ` and recency (newest source ~${Math.round(newestDays)} days old)` : '') +
  `. It is NOT a survey of how many people boycott. Verify via the sources.`;

const out = {
  brand: ctx.brand,
  brand_normalized: ctx.brand_normalized,
  status: parsed.status,
  confidence,
  reason: parsed.reason || '',
  who_is_calling: parsed.who_is_calling || '',
  recency: newestDays !== null ? `newest source ~${Math.round(newestDays)} days old` : 'unknown',
  sources,
  notes,
  last_checked: new Date().toISOString()
};
return [{ json: out }];
